gakH(){return'\u2022 TP.HCM: gi\u1edd ho\u1ea1t \u0111\u1ed9ng, kho\u1ea3ng c\xe1ch chuy\u1ebfn (t\u1ea7n su\u1ea5t) v\xe0 gi\u1edd xu\u1ea5t b\u1ebfn l\u1ea5y t\u1eeb h\u1ec7 th\u1ed1ng th\xf4ng tin xe bu\xfdt TP.HCM (apicms.ebms.vn), theo \u0111\xfang th\u1ee9 trong tu\u1ea7n.\n\u2022 H\xe0 N\u1ed9i: l\u1ea5y t\u1eeb timbus.vn (Transerco); metro 2A/3 theo OpenStreetMap.\n\u2022 Tuy\u1ebfn ch\u1ea1y theo t\u1ea7n su\u1ea5t: th\u1eddi gian ch\u1edd = m\u1ed9t n\u1eeda kho\u1ea3ng c\xe1ch chuy\u1ebfn (vd 15 ph\xfat/chuy\u1ebfn \u2192 ch\u1edd ~7 ph\xfat). V\xec v\u1eady "gi\u1edd l\xean xe" l\xe0 \u01b0\u1edbc t\xednh, kh\xf4ng ph\u1ea3i gi\u1edd xe t\u1edbi th\u1eadt.\n\u2022 Tuy\u1ebfn c\xf3 gi\u1edd xu\u1ea5t b\u1ebfn c\u1ed1 \u0111\u1ecbnh: d\xf9ng \u0111\xfang gi\u1edd xu\u1ea5t b\u1ebfn.'},
gakG(){return"Th\u1eddi gian \u0111i xe"},
gakF(){return"\u2022 TP.HCM: th\u1eddi gian ch\u1ea1y to\xe0n tuy\u1ebfn theo bi\u1ec3u \u0111\u1ed3 c\u1ee7a ngu\u1ed3n, chia cho t\u1eebng tr\u1ea1m theo qu\xe3ng \u0111\u01b0\u1eddng d\u1ecdc l\u1ed9 tr\xecnh.\n\u2022 H\xe0 N\u1ed9i: ngu\u1ed3n kh\xf4ng cho th\u1eddi gian ch\u1ea1y \u2192 \u01b0\u1edbc theo chi\u1ec1u d\xe0i l\u1ed9 tr\xecnh v\u1edbi v\u1eadn t\u1ed1c trung b\xecnh 16 km/h (bu\xfdt, \u0111\xe3 t\xednh d\u1eebng \u0111\xf3n tr\u1ea3 kh\xe1ch) v\xe0 35 km/h (metro).\n\u2022 Kh\xf4ng t\xednh k\u1eb9t xe th\u1ef1c t\u1ebf \u2014 gi\u1edd cao \u0111i\u1ec3m c\xf3 th\u1ec3 ch\u1eadm h\u01a1n."},
gakK(){return"\u0110i b\u1ed9 v\xe0 chuy\u1ec3n tuy\u1ebfn"},
gakJ(){return'\u2022 T\u1ed1c \u0111\u1ed9 \u0111i b\u1ed9 1,2 m/s (~4,3 km/h, \u0111\xe3 t\xednh ch\u1edd \u0111\xe8n). Qu\xe3ng \u0111\u01b0\u1eddng \u0111i b\u1ed9 = \u0111\u01b0\u1eddng chim bay \xd7 1,3 (\u0111\u01b0\u1eddng ph\u1ed1 quanh co).\n\u2022 \u0110i b\u1ed9 t\u1edbi tr\u1ea1m t\u1ed1i \u0111a 800 m; chuy\u1ec3n tuy\u1ebfn \u0111i b\u1ed9 t\u1ed1i \u0111a 400 m v\xe0 c\u1ea7n \xedt nh\u1ea5t 1 ph\xfat; t\u1ed1i \u0111a 4 ch\u1eb7ng xe.\n\u2022 N\u1ebfu b\u1ea1n b\u1eadt "\u0110\u01b0\u1eddng \u0111i theo ph\u1ed1", \u0111o\u1ea1n \u0111i b\u1ed9 \u0111\u01b0\u1ee3c v\u1ebd theo \u0111\u01b0\u1eddng th\u1eadt (OSRM/FOSSGIS, d\u1eef li\u1ec7u OpenStreetMap); th\u1eddi gian v\u1eabn t\xednh nh\u01b0 tr\xean.'},
gakC(){return"X\u1ebfp h\u1ea1ng ph\u01b0\u01a1ng \xe1n"},
gakB(){return'\u2022 "\u0110\u1ec1 xu\u1ea5t": gi\u1edd t\u1edbi s\u1edbm nh\u1ea5t, m\u1ed7i l\u1ea7n chuy\u1ec3n tuy\u1ebfn t\xednh th\xeam 5 ph\xfat (v\xec chuy\u1ec3n tuy\u1ebfn m\u1ec7t v\xe0 d\u1ec5 l\u1ee1 xe). Tuy\u1ebfn gi\xe1 cao (li\xean t\u1ec9nh, s\xe2n bay \u2013 V\u0169ng T\xe0u, bu\xfdt du l\u1ecbch) ch\u1ec9 \u0111\u01b0\u1ee3c \u0111\u1ec1 xu\u1ea5t khi nhanh h\u01a1n h\u1eb3n: m\u1ed7i ngh\xecn \u0111\u1ed3ng v\u01b0\u1ee3t 20.000\u0111 t\xednh nh\u01b0 ch\u1eadm th\xeam 1 ph\xfat.\n\u2022 C\xe1c ti\xeau ch\xed kh\xe1c (nhanh nh\u1ea5t, \xedt chuy\u1ec3n, r\u1ebb nh\u1ea5t, ng\u1eafn nh\u1ea5t, \xedt \u0111i b\u1ed9) \u2014 ho\xe0 th\xec x\xe9t gi\u1edd t\u1edbi.\n\u2022 Nhi\u1ec1u \u0111i\u1ec3m d\u1eebng: m\u1ed7i \u0111o\u1ea1n ch\u1ecdn ph\u01b0\u01a1ng \xe1n t\u1ed1t nh\u1ea5t theo ti\xeau ch\xed \u0111ang ch\u1ecdn; "T\u1ed1i \u01b0u th\u1ee9 t\u1ef1" th\u1eed m\u1ecdi th\u1ee9 t\u1ef1 gh\xe9 v\xe0 ch\u1ecdn th\u1ee9 t\u1ef1 t\u1edbi n\u01a1i s\u1edbm nh\u1ea5t.'},
gakz(){return"Gi\xe1 v\xe9"},
gaky(){return'\u2022 Gi\xe1 v\xe9 l\u01b0\u1ee3t c\u1ee7a t\u1eebng tuy\u1ebfn theo ngu\u1ed3n c\xf4ng b\u1ed1; t\u1ed5ng = c\u1ed9ng gi\xe1 c\xe1c ch\u1eb7ng (kh\xf4ng t\xednh v\xe9 th\xe1ng, v\xe9 ng\xe0y hay v\xe9 li\xean th\xf4ng).\n\u2022 Ch\xednh s\xe1ch c\xf3 th\u1eddi h\u1ea1n t\xednh theo NG\xc0Y b\u1ea1n \u0111i, h\u1ebft h\u1ea1n t\u1ef1 v\u1ec1 gi\xe1 th\u01b0\u1eddng. Hi\u1ec7n c\xf3: mi\u1ec5n v\xe9 134 tuy\u1ebfn bu\xfdt TP.HCM 1/7\u201331/12/2026 (theo danh s\xe1ch trong th\xf4ng c\xe1o c\u1ee7a TP.HCM; t\u1eeb 1/10 c\u1ea7n x\xe1c th\u1ef1c khi l\xean xe).\n\u2022 Metro s\u1ed1 1 t\xednh theo c\u1ef1 ly (Q\u0110 5327/Q\u0110-UBND): d\u01b0\u1edbi 5 km 7.000\u0111, 5\u201310 km 12.000\u0111, 10\u201315 km 16.000\u0111, t\u1eeb 15 km 20.000\u0111 (th\u1ebb/QR: 6.000\u201319.000\u0111). C\u1ef1 ly app \u01b0\u1edbc t\xednh theo l\u1ed9 tr\xecnh gi\u1eefa hai ga n\xean c\xf3 th\u1ec3 l\u1ec7ch m\u1ed9t b\u1eadc gi\xe1 \u1edf ranh gi\u1edbi.\n\u2022 Ch\xednh s\xe1ch gi\xe1 v\xe9 \u0111\u01b0\u1ee3c c\u1eadp nh\u1eadt c\xf9ng d\u1eef li\u1ec7u tuy\u1ebfn, kh\xf4ng c\u1ea7n c\u1eadp nh\u1eadt app.\n\u2022 Tuy\u1ebfn ch\u01b0a c\xf3 gi\xe1 trong ngu\u1ed3n \u2192 hi\u1ec7n "gi\xe1 v\xe9 ch\u01b0a r\xf5" thay v\xec \u0111o\xe1n.'},
gakt(){return"Khi h\u1ebft xe: \u0111i b\u1ed9, xe m\xe1y / taxi"},
gaks(){return'\u2022 \u0110\u01b0\u1eddng \u0111i b\u1ed9 v\xe0 \u0111\u01b0\u1eddng xe l\u1ea5y t\u1eeb OSRM (FOSSGIS, d\u1eef li\u1ec7u OpenStreetMap), ch\u1ec9 khi b\u1ea1n \u0111\xe3 cho ph\xe9p.\n\u2022 Th\u1eddi gian xe m\xe1y / taxi = l\u1ea5y m\u1ee9c ch\u1eadm h\u01a1n gi\u1eefa (th\u1eddi gian OSRM \xd7 1,3) v\xe0 (qu\xe3ng \u0111\u01b0\u1eddng \u1edf 25 km/h) \u2014 v\xec OSRM kh\xf4ng bi\u1ebft k\u1eb9t xe. Ch\u1ec9 l\xe0 \u01b0\u1edbc t\xednh.\n\u2022 "Chuy\u1ebfn s\u1edbm nh\u1ea5t" = ch\u1ea1y l\u1ea1i t\xecm \u0111\u01b0\u1eddng t\u1eeb 4:30 s\xe1ng h\xf4m sau.\n\u2022 "G\u1ea7n chuy\u1ebfn cu\u1ed1i" = l\xean xe trong v\xf2ng 30 ph\xfat tr\u01b0\u1edbc chuy\u1ebfn cu\u1ed1i theo gi\u1edd ho\u1ea1t \u0111\u1ed9ng c\xf4ng b\u1ed1.'},
gakE(){return"H\xe0nh tr\xecnh c\u1ee7a t\xf4i"},
gakD(){return"\u2022 Km \u0111i xe = qu\xe3ng \u0111\u01b0\u1eddng d\u1ecdc l\u1ed9 tr\xecnh c\xe1c ch\u1eb7ng xe; km \u0111i b\u1ed9 theo c\xe1ch t\xednh \u0111i b\u1ed9 \u1edf tr\xean.\n\u2022 S\u1ed1 b\u01b0\u1edbc \u2248 1.300 b\u01b0\u1edbc/km \u0111i b\u1ed9.\n\u2022 CO\u2082 gi\u1ea3m \u2248 50 g cho m\u1ed7i km \u0111i xe c\xf4ng c\u1ed9ng thay cho xe m\xe1y (xe m\xe1y ~90 g/km, bu\xfdt/metro ~40 g/km m\u1ed7i h\xe0nh kh\xe1ch).\n\u2022 Chuy\u1ebfn quen: \xedt nh\u1ea5t 3 l\u1ea7n c\xf9ng \u0111i\u1ec3m \u0111i\u2013\u0111\u1ebfn, c\xf9ng khung gi\u1edd (\xb190 ph\xfat) trong 6 tu\u1ea7n g\u1ea7n \u0111\xe2y."},
gakx(){return"\u0110\u1ed9 m\u1edbi c\u1ee7a d\u1eef li\u1ec7u"},
gakw(){return'\u2022 D\u1eef li\u1ec7u tuy\u1ebfn \u0111\u01b0\u1ee3c l\u1ea5y l\u1ea1i t\u1eeb ngu\u1ed3n m\u1ed7i tu\u1ea7n (3 gi\u1edd s\xe1ng th\u1ee9 Hai), ki\u1ec3m tra an to\xe0n (thi\u1ebfu tuy\u1ebfn/tr\u1ea1m b\u1ea5t th\u01b0\u1eddng th\xec kh\xf4ng ph\xe1t h\xe0nh) r\u1ed3i app t\u1ef1 t\u1ea3i; ng\xe0y c\u1eadp nh\u1eadt lu\xf4n hi\u1ec7n trong app. Qu\xe1 30 ng\xe0y ch\u01b0a c\u1eadp nh\u1eadt, app s\u1ebd c\u1ea3nh b\xe1o.\n\u2022 \u0110\u1ecba \u0111i\u1ec3m, t\xean \u0111\u01b0\u1eddng, ph\u01b0\u1eddng/x\xe3 (theo \u0111\u1ecba gi\u1edbi t\u1eeb 1/7/2025) l\u1ea5y t\u1eeb OpenStreetMap.\n\u2022 Th\u1ea5y sai? \u0110\xe1nh gi\xe1 \ud83d\udc4e v\xe0 ch\u1ecdn "Gi\u1edd ch\u1ea1y trong app sai" / "Tr\u1ea1m kh\xf4ng c\xf3" / "Tuy\u1ebfn \u0111\xe3 \u0111\u1ed5i l\u1ed9 tr\xecnh" \u2014 b\xe1o c\xe1o \u1ea9n danh \u0111\u01b0\u1ee3c t\u1ed5ng h\u1ee3p m\u1ed7i l\u1ea7n c\u1eadp nh\u1eadt.'},
gWD(){return"C\xe1ch t\xednh & \u0111\u1ed9 ch\xednh x\xe1c"},
ga_E(){return"C\xe1 nh\xe2n & c\xe0i \u0111\u1eb7t"},
ga_w(){return"C\xe1 nh\xe2n & c\xe0i \u0111\u1eb7t"},
ga_v(){return"Quy\u1ec1n ri\xeang t\u01b0"},
ga_x(){return"G\u1eedi \u0111\xe1nh gi\xe1 \u1ea9n danh"},
ga_y(){return"M\xe3 tuy\u1ebfn, tr\u1ea1m, nh\xe3n v\xe0 gi\u1edd \u0111i \u2014 gi\xfap s\u1eeda d\u1eef li\u1ec7u sai"},
ga_s(){return"\u1ee8ng d\u1ee5ng"},
ga_z(){return"Ch\u01b0a \u0111\u0103ng nh\u1eadp \u2014 d\u1eef li\u1ec7u ch\u1ec9 \u1edf tr\xean m\xe1y"},
ga_A(){return"Giao di\u1ec7n"},
ga_D(){return"Theo m\xe1y"},
ga_C(){return"S\xe1ng"},
ga_B(){return"T\u1ed1i"},
gamp(){return"Ch\u1ecdn \u1ea3nh t\u1eeb th\u01b0 vi\u1ec7n"},
gamq(){return"Xo\xe1 \u1ea3nh"},
gamo(){return"\u1ea2nh \u0111\u01b0\u1ee3c c\u1eaft vu\xf4ng v\xe0 thu nh\u1ecf (256 px, ~15 KB) tr\xean m\xe1y tr\u01b0\u1edbc khi l\u01b0u; khi \u0111\u0103ng nh\u1eadp, \u1ea3nh \u0111\u01b0\u1ee3c l\u01b0u ri\xeang t\u01b0 tr\xean m\xe1y ch\u1ee7 \u2014 ch\u1ec9 b\u1ea1n xem \u0111\u01b0\u1ee3c."},
